using FluentValidation;
using LostFound.Application.Contracts;

namespace LostFound.Application.Validation;
public sealed class CreateItemRequestValidator : AbstractValidator<CreateItemRequest> { public CreateItemRequestValidator() { RuleFor(x=>x.Title).NotEmpty().MaximumLength(160); RuleFor(x=>x.Description).NotEmpty().MaximumLength(4000); RuleFor(x=>x.CategoryId).NotEmpty(); RuleFor(x=>x.Location).NotEmpty().MaximumLength(300); RuleFor(x=>x.RewardAmount).GreaterThanOrEqualTo(0).When(x=>x.RewardAmount.HasValue); RuleFor(x=>x.Latitude).InclusiveBetween(-90,90).When(x=>x.Latitude.HasValue); RuleFor(x=>x.Longitude).InclusiveBetween(-180,180).When(x=>x.Longitude.HasValue); RuleFor(x=>x.VerificationQuestions).Must(x=>x is null || x.Count<=5); RuleForEach(x=>x.VerificationQuestions).MinimumLength(8).MaximumLength(240).When(x=>x.VerificationQuestions is not null); } }
public sealed class UpdateItemRequestValidator : AbstractValidator<UpdateItemRequest> { public UpdateItemRequestValidator() { RuleFor(x=>x.Title).NotEmpty().MaximumLength(160); RuleFor(x=>x.Description).NotEmpty().MaximumLength(4000); RuleFor(x=>x.CategoryId).NotEmpty(); RuleFor(x=>x.Location).NotEmpty().MaximumLength(300); RuleFor(x=>x.RewardAmount).GreaterThanOrEqualTo(0).When(x=>x.RewardAmount.HasValue); RuleFor(x=>x.Latitude).InclusiveBetween(-90,90).When(x=>x.Latitude.HasValue); RuleFor(x=>x.Longitude).InclusiveBetween(-180,180).When(x=>x.Longitude.HasValue); } }
